import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice builds an invoice with customer, date, and line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.customerName, 'Northwind Studio');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 5,
  });

  assert.deepEqual(result.value.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  const tests = [
    '2024-1-15',
    '2024/01/15',
    '15-01-2024',
    '2024-13-01',
    '2024-01-32',
    '2024-02-30',
    'not-a-date',
    '',
  ];

  for (const date of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Expected failure for date: ${date}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('createInvoice accepts valid dates', () => {
  const validDates = ['2024-01-31', '2024-02-29', '2025-02-28', '1970-01-01'];

  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Expected success for date: ${date}`);
  }
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns NO_LINES when lines is missing or null', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
  });

  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: null,
  });

  assert.equal(result1.ok, false);
  assert.equal(result1.error, 'NO_LINES');
  assert.equal(result2.ok, false);
  assert.equal(result2.error, 'NO_LINES');
});

test('createInvoice returns QTY_INVALID for non-positive quantity', () => {
  const tests = [0, -1, -10];

  for (const qty of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Expected failure for qty: ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  const tests = [1.5, 2.1, 0.5, '5', null, undefined];

  for (const qty of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Expected failure for qty: ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice returns UNKNOWN_SKU for product not in catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice stops at first line validation error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'UNKNOWN', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate the input lines', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  assert.equal(result.ok, true);
  assert.deepEqual(inputLines, [{ sku: 'DES-HOUR', qty: 5 }]);
  assert.notEqual(result.value.lines, inputLines);
});

test('createInvoice includes products with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // 21%
      { sku: 'PRINT-A4', qty: 1 }, // 9%
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0%
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with quantity of 1', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 100, unitPrice: 9500 };
  assert.equal(lineTotal(line), 950000);
});

test('invoiceTotals sums line totals and includes discount and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, unitPrice: 9500, name: 'Development (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 42500 + 28500 = 71000
  // VAT: (42500 + 28500) * 21 / 100 = 14910
  assert.deepEqual(totals, {
    subtotal: 71000,
    discount: 0,
    vat: 14910,
    total: 71000 + 14910,
  });
});

test('invoiceTotals works with empty lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // VAT: 120000 * 21 / 100 = 25200
  assert.deepEqual(totals, { subtotal: 120000, discount: 0, vat: 25200, total: 145200 });
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 8 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // C-001 is gold tier with 5% discount
  const subtotal = 10 * 8500 + 8 * 9500; // 161000
  const discount = subtotal * 5 / 100; // 8050
  // VAT is on amount after discount: (161000 - 8050) * 21 / 100 = 32099.5 -> 32100 (rounded)
  const amountAfterDiscount = subtotal - discount; // 152950
  const vat = amountAfterDiscount * 21 / 100; // 32119.5 -> 32120 (rounded to even)
  assert.deepEqual(totals, {
    subtotal,
    discount,
    vat: 32120,
    total: subtotal - discount + 32120,
  });
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

