  const invalidDiscounts = [-1, -0.5, 100.1, 150];

  for (const discount of invalidDiscounts) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: discount }],
    });
    assert.equal(result.ok, false, `Expected failure for discount: ${discount}`);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  }
